{
  "headline": "Ertapenem is not on FDA's shortage list as of 2026-10-21; Corvale East has 30 days on hand and Corvale General has 21.7 days on hand",
  "headline_cites": ["D3", "D1", "D2"],
  "sentences": [
    {
      "text": "FDA's drug shortage list does not include ertapenem as of 2026-10-21.",
      "cites": ["D3"]
    },
    {
      "text": "Corvale East holds 448 vials of ertapenem 1 g injection with a daily use of 14.9 vials, providing 30 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale General holds 722 vials of ertapenem 1 g injection with a daily use of 33.2 vials, providing 21.7 days on hand.",
      "cites": ["D2"]
    },
    {
      "text": "A registered manufacturing plant for ertapenem is ACS Dobfar SpA (FEI 3006028606) in Italy, which received a VAI classification on its most recent inspection ending 2024-12-13.",
      "cites": ["E14", "E12"]
    },
    {
      "text": "That plant previously received an OAI classification on an inspection ending 2016-01-19 and a Warning Letter dated 2017-01-13.",
      "cites": ["E8", "E13"]
    },
    {
      "text": "The rule-based best option is to buy from Apotex Corp., which is not on FDA's shortage list today, though its label names no plant we could place.",
      "cites": ["D4"]
    },
    {
      "text": "Alternative manufacturers ranked equally include BluePoint Laboratories and Dr.Reddys Laboratories Inc., also not on the shortage list and with no placeable plant on their labels.",
      "cites": ["D5", "D6"]
    }
  ]
}
